source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (0, 5) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] not in (0,5) and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append(cells)

    runs = []
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1; continue
            a = r
            while r < h and grid[r][c] == 5: r += 1
            if r-a > 1: runs.append(('v', a, r-1, c))
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1; continue
            a = c
            while c < w and grid[r][c] == 5: c += 1
            if c-a > 1: runs.append(('h', a, c-1, r))

    for orient, start, end, fixed in runs:
        # A seed component meets an endpoint of a 5-line on one of its sides.
        candidates = []
        for cells in comps:
            cellset = set(cells)
            choices = []
            if orient == 'v':
                for anchor, side in ((start, -1), (start, 1), (end, -1), (end, 1)):
                    nr, nc = anchor, fixed+side
                    if 0 <= nc < w and (nr, nc) in cellset:
                        choices.append((anchor, side))
                if choices:
                    # Prefer the endpoint for which the component's bounding box reaches the endpoint.
                    rmin = min(y for y,x in cells); rmax = max(y for y,x in cells)
                    choices.sort(key=lambda z: 0 if (z[0] == start and rmin == start) or (z[0] == end and rmax == end) else 1)
            else:
                for anchor, side in ((start, -1), (start, 1), (end, -1), (end, 1)):
                    nr, nc = fixed+side, anchor
                    if 0 <= nr < h and (nr, nc) in cellset:
                        choices.append((anchor, side))
                if choices:
                    cmin = min(x for y,x in cells); cmax = max(x for y,x in cells)
                    choices.sort(key=lambda z: 0 if (z[0] == start and cmin == start) or (z[0] == end and cmax == end) else 1)
            if choices:
                candidates.append((cells, choices[0]))
        if not candidates:
            continue
        # Use the closest attached seed component.
        cells, (anchor, side) = min(candidates, key=lambda item: min(abs(y-fixed)+abs(x-fixed) for y,x in item[0]))
        r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
        c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
        motif = [[grid[y][x] for x in range(c0,c1+1)] for y in range(r0,r1+1)]
        if orient == 'v':
            period = r1-r0+1
            for r in range(start, end+1):
                k = (r-anchor) % period
                src_r = (r0+k) if anchor == start else (r1-k)
                for x in range(c0,c1+1):
                    yidx = src_r-r0
                    if 0 <= x < w and 0 <= r < h and grid[r][x] != 5:
                        out[r][x] = motif[yidx][x-c0]
        else:
            period = c1-c0+1
            for c in range(start, end+1):
                k = (c-anchor) % period
                src_c = (c0+k) if anchor == start else (c1-k)
                for y in range(r0,r1+1):
                    if 0 <= y < h and 0 <= c < w and grid[y][c] != 5:
                        out[y][c] = motif[y-r0][src_c-c0]
    return out
